import gzip, math, sys, statistics
from collections import defaultdict

def open_any(path):
    # Read gzip or plain text transparently.
    with open(path, 'rb') as f:
        magic = f.read(2)
    if magic == b'\\x1f\\x8b':
        return gzip.open(path, 'rt')
    return open(path, 'rt')

def read_summary(path, window=750_000, max_leads=12):
    rows = []
    with open_any(path) as f:
        header = f.readline().rstrip('\\n').split('\\t')
        cols = {c:i for i,c in enumerate(header)}
        for line in f:
            p = line.rstrip('\\n').split('\\t')
            if len(p) < 7:
                continue
            chrom = p[cols['CHR']]
            pos = int(p[cols['POS']])
            pval = p[cols['P']]
            if pval == 'NA':
                continue
            pval = float(pval)
            if pval <= 0 or pval >= 1:
                continue
            rows.append((pval, pos, p[cols['RSID']], p[cols['SNPID']], chrom,
                         p[cols['EFFECT_ALLELE']], p[cols['OTHER_ALLELE']]))
    rows.sort()
    leads = []
    for pval, pos, rsid, snpid, chrom, ea, oa in rows:
        if all(abs(pos - lead_pos) > 1_000_000 for _, lead_pos, *_ in leads):
            leads.append((pval, pos, rsid, snpid, chrom, ea, oa))
        if len(leads) >= max_leads:
            break
    by_pos = defaultdict(list)
    for pval, pos, rsid, snpid, chrom, ea, oa in rows:
        for lead_idx, (lpval, lead_pos, *_rest) in enumerate(leads):
            if abs(pos - lead_pos) <= window:
                by_pos[pos].append((pval, lead_idx, rsid, snpid, ea, oa))
                break
    return leads, by_pos

def read_panel(path):
    sample_pop = {}
    with open_any(path) as f:
        header = f.readline().rstrip('\\n').split('\\t')
        idx = {c:i for i,c in enumerate(header)}
        for line in f:
            p = line.rstrip('\\n').split('\\t')
            if len(p) >= 3:
                sample_pop[p[idx['sample']]] = p[idx['super_pop']]
    return sample_pop

def mean(xs):
    return sum(xs) / len(xs)

def std(xs):
    m = mean(xs)
    return math.sqrt(sum((x-m)**2 for x in xs) / (len(xs)-1))

def pearson(xs, ys):
    if len(xs) < 3:
        return float('nan')
    sx = std(xs); sy = std(ys)
    if sx == 0 or sy == 0:
        return float('nan')
    mx = mean(xs); my = mean(ys)
    cov = sum((x-mx)*(y-my) for x,y in zip(xs,ys)) / (len(xs)-1)
    return cov / (sx*sy)

def rankdata(vals):
    order = sorted(range(len(vals)), key=lambda i: vals[i])
    ranks = [0.0]*len(vals)
    i = 0
    while i < len(order):
        j = i + 1
        while j < len(order) and vals[order[j]] == vals[order[i]]:
            j += 1
        avg = (i + j + 1) / 2.0  # 1-based average rank over positions i..j-1 => (i+1+j)/2
        for k in range(i, j):
            ranks[order[k]] = avg
        i = j
    return ranks

def spearman(xs, ys):
    if len(xs) < 3:
        return float('nan')
    return pearson(rankdata(xs), rankdata(ys))

def normal_inv_cdf(p):
    # p is upper-tail probability; return z such that P(Z > z)=p for small p.
    if p <= 0:
        return 8.0
    if p >= 1:
        return 0.0
    # NormalDist.inv_cdf gives z for lower-tail CDF. Use upper-tail p -> lower 1-p.
    return statistics.NormalDist().inv_cdf(1.0 - p)

def chi2_from_p(p):
    z = normal_inv_cdf(p / 2.0)
    return z * z

def parse_dosage(gt):
    if not gt:
        return float('nan')
    if gt[0] == '.':
        return float('nan')
    g = 0
    if gt[0] == '1':
        g += 1
    if len(gt) >= 3 and gt[2] == '1':
        g += 1
    return float(g)

def main():
    summary_path, vcf_path, panel_path, out_path = sys.argv[1:5]
    leads, by_pos = read_summary(summary_path)
    if len(leads) < 3:
        raise SystemExit('Too few independent lead loci')
    sample_pop = read_panel(panel_path)

    records = defaultdict(list)  # lead_idx -> list of (pos, rsid, pval, dosage_list)
    samples = []
    lead_gt = {}
    with open_any(vcf_path) as f:
        for line in f:
            if line.startswith('##'):
                continue
            if line.startswith('#CHROM'):
                samples = line.rstrip('\\n').split('\\t')[9:]
                continue
            parts = line.rstrip('\\n').split('\\t')
            if len(parts) < 10:
                continue
            chrom = parts[0]
            pos = int(parts[1])
            ref = parts[3]
            alt = parts[4]
            if chrom "'!= '"'1' or len(ref) "'!= 1 or len(alt) != 1 or '"',' in alt:
                continue
            if pos not in by_pos:
                continue
            match = None
            for pval, lead_idx, rsid, snpid, ea, oa in by_pos[pos]:
                if {ea, oa} == {ref, alt}:
                    match = (pval, lead_idx, rsid)
                    break
            if match is None:
                continue
            fields = parts[9:]
            dosage = [parse_dosage(f.split(':', 1)[0]) for f in fields]
            pval, lead_idx, rsid = match
            records[lead_idx].append((pos, rsid, pval, dosage))
            lead_pos = leads[lead_idx][1]
            if pos == lead_pos:
                lead_gt[lead_idx] = dosage

    if not samples or len(set(sample_pop.get(s, 'OTHER') for s in samples) & {'AFR','AMR','EAS','EUR','SAS'}) < 3:
        raise SystemExit('VCF samples or panel population labels could not be read correctly')

    # Index samples by super-population.
    pop_indices = defaultdict(list)
    for i, s in enumerate(samples):
        sp = sample_pop.get(s)
        if sp in ('AFR','AMR','EAS','EUR','SAS'):
            pop_indices[sp].append(i)

    pop_rows = []
    for pop in ('AFR','AMR','EAS','EUR','SAS'):
        idx = pop_indices[pop]
        if not idx:
            continue
        all_x = []
        all_y = []
        per_locus_rmse = []
        valid_variants = 0
        for li, lead in enumerate(leads):
            if li not in lead_gt or li not in records:
                continue
            gl = [lead_gt[li][j] for j in idx]
            if std([g for g in gl if g == g]) == 0 or len([g for g in gl if g == g]) < 10:
                continue
            lead_chi2 = chi2_from_p(lead[0])
            xs = []
            ys = []
            for pos, rsid, pval, dosage in records[li]:
                gv = [dosage[j] for j in idx]
                valid = [(a,b) for a,b in zip(gl,gv) if a == a and b == b]
                if len(valid) < 10:
                    continue
                a = [v[0] for v in valid]
                b = [v[1] for v in valid]
                if std(a) == 0 or std(b) == 0:
                    continue
                r = pearson(a, b)
                r2 = r * r
                y = min(chi2_from_p(pval) / lead_chi2, 1.5)
                xs.append(r2)
                ys.append(y)
                all_x.append(r2)
                all_y.append(y)
            if len(xs) >= 5:
                rmse = math.sqrt(sum((x-y)**2 for x,y in zip(xs,ys)) / len(xs))
                per_locus_rmse.append(rmse)
        if len(all_x) < 50:
            continue
        pr = pearson(all_x, all_y)
        sp = spearman(all_x, all_y)
        rmse = math.sqrt(sum((x-y)**2 for x,y in zip(all_x,all_y)) / len(all_x))
        mean_locus_rmse = mean(per_locus_rmse) if per_locus_rmse else float('nan')
        label = {'AFR':'AFR','AMR':'HIS','EAS':'EAS','EUR':'EUR','SAS':'SAS'}[pop]
        pop_rows.append((pr, pop, label, pr, sp, rmse, mean_locus_rmse, len(all_x)))

    pop_rows.sort(reverse=True, key=lambda r: r[0])
    with open(out_path, 'w') as out:
        out.write('population\\tlabel\\tpearson\\tspearman\\trmse\\tmean_locus_rmse\\tvariants\\n')
        for _, pop, label, pr, sp, rmse, mlr, n in pop_rows:
            out.write(f'{pop}\\t{label}\\t{pr:.6f}\\t{sp:.6f}\\t{rmse:.6f}\\t{mlr:.6f}\\t{n}\\n')
    best = pop_rows[0][1]
    print('best_population', best)
    print('scores_written', out_path)

if __name__ == '__main__':
    main()
