        if len(all_x) < 50:
            continue
        pr = pearson(all_x, all_y)
        sp = spearman(all_x, all_y)
        rmse = math.sqrt(sum((x-y)**2 for x,y in zip(all_x,all_y)) / len(all_x))
        mean_locus_rmse = mean(per_locus_rmse) if per_locus_rmse else float('nan')
        label = {'AFR':'AFR','AMR':'HIS','EAS':'EAS','EUR':'EUR','SAS':'SAS'}[pop]
        pop_rows.append((pr, pop, label, pr, sp, rmse, mean_locus_rmse, len(all_x)))

    pop_rows.sort(reverse=True, key=lambda r: r[0])
    with open(out_path, 'w') as out:
        out.write('population\\tlabel\\tpearson\\tspearman\\trmse\\tmean_locus_rmse\\tvariants\\n')
        for _, pop, label, pr, sp, rmse, mlr, n in pop_rows:
            out.write(f'{pop}\\t{label}\\t{pr:.6f}\\t{sp:.6f}\\t{rmse:.6f}\\t{mlr:.6f}\\t{n}\\n')
    best = pop_rows[0][1]
    print('best_population', best)
    print('scores_written', out_path)

if __name__ == '__main__':
    main()
